import type { ComponentProps, ReactNode } from "react";
import { useEffect, useId, useRef, useState } from "react";
import { Button } from "./button";
import type { AgentRunStatus } from "./agent-status";
import { cn } from "./utils";

type AgentMemberStatus = AgentRunStatus | "skipped";

type AgentMember = {
    id: string;
    name: string;
    role: string;
    provider: string;
    model: string;
    status: AgentMemberStatus;
    summary?: ReactNode;
    result?: ReactNode;
    error?: ReactNode;
};

type AgentTeamMemberAction = (
    memberId: string,
    member: AgentMember,
) => void | Promise<void>;

type AgentTeamProps = Omit<
    ComponentProps<"section">,
    "aria-label" | "aria-labelledby" | "children"
> & {
    id: string;
    name: string;
    members: readonly AgentMember[];
    variant?: "panel" | "compact";
    loading?: boolean;
    disabled?: boolean;
    actionPending?: boolean;
    onCancelMember?: AgentTeamMemberAction;
    onRetryMember?: AgentTeamMemberAction;
    onSkipMember?: AgentTeamMemberAction;
};

type MemberAction = "cancel" | "retry" | "skip";

type MemberActionState = {
    identity: object;
    action: MemberAction;
    pending: boolean;
    error?: string;
};

type InFlightRequest = { identity: object };

const statusLabels: Record<AgentMemberStatus, string> = {
    queued: "대기",
    running: "진행 중",
    completed: "완료",
    failed: "실패",
    cancelled: "취소됨",
    paused: "일시 정지",
    "awaiting-input": "입력 대기",
    "awaiting-approval": "승인 대기",
    skipped: "건너뜀",
};

const memberActions: Record<MemberAction, {
    label: string;
    callback: "onCancelMember" | "onRetryMember" | "onSkipMember";
    availableFor: readonly AgentMemberStatus[];
}> = {
    cancel: {
        label: "작업 취소",
        callback: "onCancelMember",
        availableFor: [
            "queued", "running", "paused", "awaiting-input",
            "awaiting-approval",
        ],
    },
    retry: {
        label: "다시 시도",
        callback: "onRetryMember",
        availableFor: ["failed", "cancelled"],
    },
    skip: {
        label: "건너뛰기",
        callback: "onSkipMember",
        availableFor: ["queued"],
    },
};

const summaryStatusOrder: readonly AgentMemberStatus[] = [
    "running",
    "awaiting-approval",
    "awaiting-input",
    "queued",
    "paused",
    "failed",
    "cancelled",
    "skipped",
    "completed",
];

function isReadonlyArrayOf<T>(value: unknown): value is readonly T[] {
    return Array.isArray(value);
}

function errorMessage(error: unknown) {
    if (error instanceof Error && error.message.trim()) {
        return error.message.trim();
    }
    if (typeof error === "string" && error.trim()) return error.trim();
    return "작업을 처리하지 못했습니다.";
}

function summarizeMembers(members: readonly AgentMember[]) {
    if (members.length === 0) return "멤버 없음";
    const counts = new Map<AgentMemberStatus, number>();
    for (const member of members) {
        counts.set(member.status, (counts.get(member.status) ?? 0) + 1);
    }
    const details = summaryStatusOrder
        .filter((status) => counts.has(status))
        .map((status) => `${counts.get(status)} ${statusLabels[status]}`);
    return `${members.length}명 · ${details.join(" · ")}`;
}

function memberScopeKey(teamId: string, memberId: string) {
    return JSON.stringify([teamId, memberId]);
}

function AgentTeam({
    id,
    name,
    members,
    variant = "panel",
    loading = false,
    disabled = false,
    actionPending = false,
    onCancelMember,
    onRetryMember,
    onSkipMember,
    className,
    ...props
}: AgentTeamProps) {
    const sectionId = useId();
    const titleId = `${sectionId}-title`;
    const identitiesRef = useRef({
        teamId: id,
        members: new Map<string, object>(),
    });
    const identities = new Map<string, object>();
    const [actionStates, setActionStates] = useState<
        ReadonlyMap<string, MemberActionState>
    >(() => new Map());
    const inFlightRef = useRef(new Map<string, InFlightRequest>());
    const callbacksRef = useRef({
        onCancelMember,
        onRetryMember,
        onSkipMember,
    });
    const mountedRef = useRef(true);
    callbacksRef.current = { onCancelMember, onRetryMember, onSkipMember };

    useEffect(() => {
        mountedRef.current = true;
        return () => {
            mountedRef.current = false;
            inFlightRef.current.clear();
        };
    }, []);

    if (typeof id !== "string" || !id.trim() ||
        typeof name !== "string" || !name.trim()) {
        throw new Error("AgentTeam requires an ID and name.");
    }
    if (variant !== "panel" && variant !== "compact") {
        throw new Error("AgentTeam has an unsupported variant.");
    }

    if (!isReadonlyArrayOf<AgentMember>(members)) {
        throw new Error("AgentTeam members must be an array.");
    }
    const previousIdentities = identitiesRef.current;
    const ids = new Set<string>();
    for (const member of members) {
        if (!member || typeof member.id !== "string" ||
            !member.id.trim() || ids.has(member.id)) {
            throw new Error("AgentTeam members need unique IDs.");
        }
        if (typeof member.name !== "string" || !member.name.trim() ||
            typeof member.role !== "string" || !member.role.trim() ||
            typeof member.provider !== "string" || !member.provider.trim() ||
            typeof member.model !== "string" || !member.model.trim() ||
            !Object.hasOwn(statusLabels, member.status)) {
            throw new Error(
                "AgentTeam members need names, metadata and valid statuses.",
            );
        }
        ids.add(member.id);
        identities.set(
            member.id,
            previousIdentities.teamId === id
                ? previousIdentities.members.get(member.id) ?? {}
                : {},
        );
    }
    identitiesRef.current = { teamId: id, members: identities };

    const isCurrentMember = (
        teamId: string,
        memberId: string,
        identity: object,
    ) => identitiesRef.current.teamId === teamId &&
        identitiesRef.current.members.get(memberId) === identity;

    const setMemberState = (
        teamId: string,
        memberId: string,
        identity: object,
        state: MemberActionState | undefined,
    ) => {
        setActionStates((current) => {
            if (!mountedRef.current ||
                !isCurrentMember(teamId, memberId, identity)) {
                return current;
            }
            const next = new Map(current);
            const scopeKey = memberScopeKey(teamId, memberId);
            if (state) next.set(scopeKey, state);
            else if (next.get(scopeKey)?.identity === identity) {
                next.delete(scopeKey);
            }
            return next;
        });
    };

    const clearMemberState = (scopeKey: string, identity: object) => {
        setActionStates((current) => {
            if (!mountedRef.current ||
                current.get(scopeKey)?.identity !== identity) {
                return current;
            }
            const next = new Map(current);
            next.delete(scopeKey);
            return next;
        });
    };

    const runAction = async (
        action: MemberAction,
        member: AgentMember,
        teamId: string,
        identity: object,
    ) => {
        const definition = memberActions[action];
        const callback = callbacksRef.current[definition.callback];
        const scopeKey = memberScopeKey(teamId, member.id);
        const inFlight = inFlightRef.current.get(scopeKey);
        if (!callback || disabled || actionPending ||
            inFlight?.identity === identity) return;
        if (!definition.availableFor.includes(member.status)) return;

        const requestEntry = { identity };
        inFlightRef.current.set(scopeKey, requestEntry);
        setMemberState(teamId, member.id, identity, {
            identity,
            action,
            pending: true,
        });

        try {
            await callback(member.id, member);
            if (inFlightRef.current.get(scopeKey) === requestEntry) {
                inFlightRef.current.delete(scopeKey);
            }
            clearMemberState(scopeKey, identity);
        } catch (error) {
            if (inFlightRef.current.get(scopeKey) === requestEntry) {
                inFlightRef.current.delete(scopeKey);
            }
            if (isCurrentMember(teamId, member.id, identity)) {
                setMemberState(teamId, member.id, identity, {
                    identity,
                    action,
                    pending: false,
                    error: errorMessage(error),
                });
            } else {
                clearMemberState(scopeKey, identity);
            }
        }
    };

    return (
        <section id={id} aria-labelledby={titleId} data-ui="agent-team"
            data-team-id={id} data-variant={variant}
            data-surface={variant === "panel" ? "panel" : undefined}
            aria-disabled={disabled || undefined}
            className={cn(
                "min-w-0 text-foreground",
                variant === "panel"
                    ? "rounded-sm border border-border bg-surface " +
                        "p-[var(--space-4)]"
                    : "min-w-0",
                className,
            )} {...props}>
            <header data-slot={variant === "panel" ? "surface-header" : undefined}
                className="flex min-w-0 flex-wrap items-start justify-between gap-2">
                <div className="min-w-0 flex-1">
                    <h2 id={titleId} data-slot="surface-title"
                        className="m-0 break-words text-sm font-semibold">
                        {name}
                    </h2>
                    <p role="status" className="m-0 text-xs text-muted">
                        {loading && members.length === 0
                            ? "멤버를 불러오는 중"
                            : summarizeMembers(members)}
                    </p>
                </div>
            </header>

            {members.length > 0 ? (
                <ol aria-label={`${name} 멤버 목록`} className={cn(
                    "m-0 grid list-none divide-y divide-border p-0",
                    variant === "panel"
                        ? "mt-[var(--space-3)]"
                        : "mt-[var(--space-2)]",
                )}>
                    {members.map((member, index) => {
                        const identity = identities.get(member.id)!;
                        const scopeKey = memberScopeKey(id, member.id);
                        const storedState = actionStates.get(scopeKey);
                        const memberState = storedState?.identity === identity
                            ? storedState : undefined;
                        const actionButtons = (Object.keys(memberActions) as
                            MemberAction[]).filter((action) =>
                            Boolean(callbacksRef.current[
                                memberActions[action].callback
                            ]) && memberActions[action].availableFor.includes(
                                member.status,
                            )
                        );
                        const memberTitleId = `${sectionId}-member-${index}`;

                        return (
                            <li key={member.id} data-member-id={member.id}
                                data-status={member.status}
                                aria-busy={memberState?.pending || undefined}
                                className="min-w-0 py-[var(--space-3)]">
                                <article aria-labelledby={memberTitleId}
                                    className="min-w-0">
                                    <div className="flex min-w-0 flex-wrap items-start justify-between gap-2">
                                        <div className="min-w-0 flex-1">
                                            <h3 id={memberTitleId}
                                                className="m-0 break-words text-sm font-medium">
                                                {member.name}
                                            </h3>
                                            <div className="mt-1 flex min-w-0 flex-wrap gap-x-3 gap-y-1 text-xs text-muted">
                                                <span className="min-w-0 break-words">
                                                    역할: {member.role}
                                                </span>
                                                <span className="min-w-0 break-words">
                                                    Provider: {member.provider}
                                                </span>
                                                <span className="min-w-0 break-words">
                                                    모델: {member.model}
                                                </span>
                                            </div>
                                        </div>
                                        <span role="status" className={cn(
                                            "shrink-0 text-xs",
                                            member.status === "failed"
                                                ? "text-danger"
                                                : member.status === "completed"
                                                    ? "text-accent"
                                                    : (member.status === "running" ||
                                                        member.status === "awaiting-approval")
                                                        ? "text-accent" : "text-muted",
                                        )}>
                                            {statusLabels[member.status]}
                                        </span>
                                    </div>

                                    {member.summary != null && (
                                        <div className="mt-2 min-w-0 break-words text-sm">
                                            <span className="text-xs font-medium text-muted">
                                                요약
                                            </span>
                                            <div>{member.summary}</div>
                                        </div>
                                    )}
                                    {member.result != null && (
                                        <div className="mt-2 min-w-0 break-words text-sm">
                                            <span className="text-xs font-medium text-muted">
                                                결과
                                            </span>
                                            <div>{member.result}</div>
                                        </div>
                                    )}
                                    {member.error != null && (
                                        <div className="mt-2 min-w-0 break-words text-sm text-danger">
                                            <span className="text-xs font-medium">
                                                오류
                                            </span>
                                            <div role="alert">{member.error}</div>
                                        </div>
                                    )}

                                    {(actionButtons.length > 0 || memberState) && (
                                        <div className="mt-2 flex min-w-0 flex-wrap items-center gap-1">
                                            {actionButtons.map((action) => {
                                                const definition =
                                                    memberActions[action];
                                                const pending = Boolean(
                                                    memberState?.pending ||
                                                    actionPending,
                                                );
                                                return (
                                                    <Button key={action}
                                                        type="button"
                                                        variant="outline"
                                                        disabled={disabled || pending}
                                                        aria-label={`${member.name} ${definition.label}`}
                                                        onClick={() => {
                                                            void runAction(
                                                                action,
                                                                member,
                                                                id,
                                                                identity,
                                                            );
                                                        }}>
                                                        {memberState?.pending &&
                                                            memberState.action === action
                                                            ? "처리 중"
                                                            : definition.label}
                                                    </Button>
                                                );
                                            })}
                                            {memberState?.error && (
                                                <span role="alert" className="text-xs text-danger">
                                                    요청 실패: {memberState.error}
                                                </span>
                                            )}
                                        </div>
                                    )}
                                </article>
                            </li>
                        );
                    })}
                </ol>
            ) : (
                <p role="status" className="m-0 mt-[var(--space-3)] text-sm text-muted">
                    {loading
                        ? "멤버를 불러오는 중입니다."
                        : "표시할 멤버가 없습니다."}
                </p>
            )}
            {members.length > 0 && loading && (
                <p role="status" className="m-0 pt-2 text-xs text-muted">
                    추가 멤버를 불러오는 중입니다.
                </p>
            )}
        </section>
    );
}

export { AgentTeam };
export type {
    AgentMember, AgentMemberStatus, AgentTeamMemberAction, AgentTeamProps,
};
